export const CLASSES = {
  swordsman: {
    id: 'swordsman',
    name: 'Swordsman',
    order: '01',
    title: 'The Lionblade',
    role: 'Frontline Duelist',
    difficulty: 'Balanced',
    color: '#eab45f',
    dark: '#6e441d',
    glow: '#ffd88a',
    description: 'A knight of the royal vanguard. Closes distance, breaks guards, and turns the tide with a lion’s roar.',
    hp: 280, mp: 90, stamina: 115, speed: 9.4,
