    const head = new THREE.Group(); head.position.y = 2.4; rig.add(head);
    add(head, new THREE.BoxGeometry(0.5, 0.5, 0.48), skin, 0, 0, 0);
    add(head, new THREE.ConeGeometry(0.06, 0.16, 4), toon('#e8dcc0'), -0.16, -0.2, 0.24);
    add(head, new THREE.ConeGeometry(0.06, 0.16, 4), toon('#e8dcc0'), 0.16, -0.2, 0.24);
    add(head, new THREE.SphereGeometry(0.05, 6, 4), basic('#ffb347'), -0.13, 0.08, 0.25, false);
    add(head, new THREE.SphereGeometry(0.05, 6, 4), basic('#ffb347'), 0.13, 0.08, 0.25, false);
    if (ogre) {
      add(head, new THREE.CylinderGeometry(0.2, 0.25, 0.2, 6), toon('#3a2f46'), 0, 0.32, 0);
      const horn = new THREE.ConeGeometry(0.08, 0.4, 5);
      add(head, horn, toon('#d8d4c4'), -0.18, 0.4, 0).rotation.z = 0.4;
      add(head, horn, toon('#d8d4c4'), 0.18, 0.4, 0).rotation.z = -0.4;
    }
    const armL = limb(rig, 0.2, 0.9, 0.22, skin, -0.6, 2.0, 0);
    const armR = limb(rig, 0.2, 0.9, 0.22, skin, 0.6, 2.0, 0);
    anim.arms.push(armL, armR);
    const weapon = new THREE.Group(); armR.add(weapon); weapon.position.y = -0.86;
    add(weapon, new THREE.CylinderGeometry(0.06, 0.08, 1.0, 6), toon('#5f4329'), 0, 0, 0);
    const headAxe = add(weapon, new THREE.BoxGeometry(0.5, 0.42, 0.1), toon('#a7b1b8'), 0.26, 0.36, 0);
    headAxe.rotation.z = -0.2;
    if (ogre) {
      add(weapon, new THREE.ConeGeometry(0.06, 0.24, 4), toon('#d6d0bc'), -0.16, 0.56, 0);
      add(weapon, new THREE.ConeGeometry(0.06, 0.24, 4), toon('#d6d0bc'), 0.22, 0.62, 0);
    }
    root.scale.setScalar(scale * (ogre ? 1.5 : 1.15));
    anim.kind = 'biped';
  } else if (type === 'wraith' || type === 'lich') {
    const lich = type === 'lich';
    const robe = toon(lich ? '#3c2f63' : '#4e5478');
    const trim = toon(lich ? '#c4a7ff' : '#9aa4d8');
    const body = add(rig, new THREE.ConeGeometry(0.55, 1.75, 8, 1, true), robe, 0, 1.05, 0);
    const hood = add(rig, new THREE.SphereGeometry(0.42, 10, 8, 0, Math.PI * 2, 0, Math.PI * 0.7), robe, 0, 2.0, 0);
    const face = add(rig, new THREE.SphereGeometry(0.24, 8, 6), toon('#1a1b2a'), 0, 1.94, 0.12, false);
    const eyeMat = basic(lich ? '#c58bff' : '#7ff0ff');
    add(rig, new THREE.SphereGeometry(0.05, 6, 4), eyeMat, -0.09, 1.98, 0.32, false);
    add(rig, new THREE.SphereGeometry(0.05, 6, 4), eyeMat, 0.09, 1.98, 0.32, false);
    add(rig, new THREE.TorusGeometry(0.55, 0.05, 6, 18), trim, 0, 1.7, 0).rotation.x = Math.PI / 2;
    const armL = limb(rig, 0.13, 0.55, 0.14, robe, -0.5, 1.65, 0);
    const armR = limb(rig, 0.13, 0.55, 0.14, robe, 0.5, 1.65, 0);
    anim.arms.push(armL, armR);
    const staff = new THREE.Group(); armR.add(staff); staff.position.y = -0.55;
    add(staff, new THREE.CylinderGeometry(0.035, 0.045, 1.7, 6), toon('#4a3c56'), 0, 0.2, 0);
    add(staff, new THREE.OctahedronGeometry(0.17), toon(lich ? '#c48bff' : '#76e5ff', { emissive: lich ? '#7d4bd6' : '#3a9ec9', emissiveIntensity: 2 }), 0, 1.15, 0, false);
    if (lich) {
      const crown = add(rig, new THREE.CylinderGeometry(0.3, 0.34, 0.16, 6, 1, true), toon('#d8bc6a'), 0, 2.38, 0);
      for (let i = 0; i < 4; i++) {
        const s = add(rig, new THREE.ConeGeometry(0.05, 0.25, 4), toon('#e6d28c'), 0, 2.56, 0);
        s.position.x = -0.18 + i * 0.12;
      }
    }
    root.scale.setScalar(scale * (lich ? 1.9 : 1.15));
    anim.kind = 'float';
    anim.hover = true;
  } else {
    // fallback shade
    add(rig, new THREE.ConeGeometry(0.5, 2.2, 8), toon('#444'), 0, 1.1, 0);
    root.scale.setScalar(scale);
  }
  root.traverse(o => { if (o.isMesh) o.castShadow = true; });
  root.userData.anim = anim;
  return root;
}

export function buildNpcModel(palette = {}) {
  const root = new THREE.Group();
  const robe = toon(palette.robe ?? '#7a6a4e');
  const skin = toon('#efc39a');
  const trim = toon(palette.trim ?? '#c8b06a');
  const body = addMesh(root, new THREE.ConeGeometry(0.44, 1.6, 8, 1, true), robe, 0, 0.85, 0);
  const head = addMesh(root, new THREE.SphereGeometry(0.3, 10, 8), skin, 0, 1.85, 0);
  const hair = addMesh(root, new THREE.SphereGeometry(0.32, 10, 8), toon(palette.hair ?? '#5b3d2b'), 0, 1.95, 0.03);
  hair.scale.set(1, 0.7, 0.95);
  addMesh(root, new THREE.CylinderGeometry(0.46, 0.46, 0.07, 12), trim, 0, 1.35, 0);
  addMesh(root, new THREE.SphereGeometry(0.05, 6, 4), basic('#2a3036'), -0.1, 1.85, 0.27, false);
  addMesh(root, new THREE.SphereGeometry(0.05, 6, 4), basic('#2a3036'), 0.1, 1.85, 0.27, false);
  if (palette.hood) {
    const hood = addMesh(root, new THREE.SphereGeometry(0.38, 10, 8, 0, Math.PI * 2, 0, Math.PI * 0.7), robe, 0, 1.9, 0);
  }
  root.userData.anim = { kind: 'npc', phase: Math.random() * 8, head, body };
  root.traverse(o => { if (o.isMesh) o.castShadow = true; });
  return root;
}

import * as THREE from 'three';
import { toon, basic, addMesh, labelSprite, buildNpcModel } from './models.js';
import { DUNGEONS, VILLAGES } from './data.js';

function canvasTex(size, draw, repeat = [1, 1]) {
  const c = document.createElement('canvas');
  c.width = c.height = size;
  draw(c.getContext('2d'), size);
  const t = new THREE.CanvasTexture(c);
  t.wrapS = t.wrapT = THREE.RepeatWrapping;
  t.repeat.set(repeat[0], repeat[1]);
  t.colorSpace = THREE.SRGBColorSpace;
  t.anisotropy = 8;
  return t;
}

function grassTex() {
  return canvasTex(256, (g, s) => {
    g.fillStyle = '#76a45d'; g.fillRect(0, 0, s, s);
    for (let i = 0; i < 4200; i++) {
      const x = Math.random() * s, y = Math.random() * s;
      g.fillStyle = ['#6b9754', '#83b168', '#5e8c4d', '#8dbb6e', '#79a861'][(Math.random() * 5) | 0];
      g.globalAlpha = 0.35 + Math.random() * 0.4;
      g.fillRect(x, y, 1.5 + Math.random() * 2.4, 1.5 + Math.random() * 3);
    }
    g.globalAlpha = 1;
  }, [110, 110]);
}

function dirtTex() {
  return canvasTex(128, (g, s) => {
    g.fillStyle = '#b99a68'; g.fillRect(0, 0, s, s);
    for (let i = 0; i < 900; i++) {
      g.fillStyle = ['#a8895a', '#c7a978', '#997c50'][(Math.random() * 3) | 0];
      g.globalAlpha = 0.3 + Math.random() * 0.35;
      g.beginPath(); g.arc(Math.random() * s, Math.random() * s, 1 + Math.random() * 3, 0, 7); g.fill();
    }
    g.globalAlpha = 1;
  }, [26, 26]);
}

function cobbleTex() {
  return canvasTex(256, (g, s) => {
    g.fillStyle = '#9a9581'; g.fillRect(0, 0, s, s);
    for (let y = 0; y < 8; y++) {
      for (let x = 0; x < 8; x++) {
        const px = x * 32 + (y % 2) * 16 + 2, py = y * 32 + 2;
        g.fillStyle = ['#b3ad99', '#a29c87', '#c2bca8', '#96917f'][(Math.random() * 4) | 0];
        g.beginPath();
        g.roundRect(px, py, 28, 28, 7);
        g.fill();
        g.strokeStyle = '#807b6a'; g.lineWidth = 2; g.stroke();
      }
    }
  }, [16, 16]);
}

function forestFloorTex() {
  return canvasTex(256, (g, s) => {
    g.fillStyle = '#4f7a48'; g.fillRect(0, 0, s, s);
    for (let i = 0; i < 2600; i++) {
      g.fillStyle = ['#456d3e', '#5b8650', '#3b5f37', '#6b9457'][(Math.random() * 4) | 0];
      g.globalAlpha = 0.4 + Math.random() * 0.5;
      g.fillRect(Math.random() * s, Math.random() * s, 2 + Math.random() * 3, 2 + Math.random() * 4);
    }
    g.globalAlpha = 1;
  }, [60, 60]);
}

export function buildWorld(scene) {
  const root = new THREE.Group();
  scene.add(root);
  const overworld = new THREE.Group();
  root.add(overworld);
  const colliders = [];
  const npcs = [];
  const portals = [];
  const labels = [];
  const animators = [];
  const villages = [];

  const addColliderBox = (cx, cz, w, d) => colliders.push({ type: 'box', minX: cx - w / 2, maxX: cx + w / 2, minZ: cz - d / 2, maxZ: cz + d / 2 });
  const addColliderCircle = (cx, cz, r) => colliders.push({ type: 'circle', x: cx, z: cz, r });

  // ---------- ground ----------
  const groundMat = toon('#ffffff');
  groundMat.map = grassTex();
  groundMat.color.set('#cfe8bd');
  const ground = new THREE.Mesh(new THREE.PlaneGeometry(3800, 3800, 1, 1), groundMat);
  ground.rotation.x = -Math.PI / 2;
  ground.receiveShadow = true;
  overworld.add(ground);

  // subtle hill discs
  for (let i = 0; i < 26; i++) {
    const a = Math.random() * Math.PI * 2, r = 750 + Math.random() * 520;
    const x = Math.cos(a) * r, z = Math.sin(a) * r;
    if (Math.abs(x) < 380 && Math.abs(z) < 380) continue;
    const h = 10 + Math.random() * 26;
    const hill = new THREE.Mesh(new THREE.ConeGeometry(50 + Math.random() * 70, h, 9), toon(i % 2 ? '#6e9a5e' : '#7fa66a'));
    hill.position.set(x, h / 2 - 1, z);
    hill.receiveShadow = true;
    overworld.add(hill);
  }

  // ---------- roads ----------
  function ribbon(points, width, mat, y = 0.04, segs = 120) {
    const curve = new THREE.CatmullRomCurve3(points.map(p => new THREE.Vector3(p[0], y, p[1])));
    const pos = [], uv = [], idx = [];
    for (let i = 0; i <= segs; i++) {
      const t = i / segs;
      const p = curve.getPoint(t);
      const tan = curve.getTangent(t).normalize();
      const n = new THREE.Vector3(-tan.z, 0, tan.x).multiplyScalar(width / 2);
      pos.push(p.x + n.x, y, p.z + n.z, p.x - n.x, y, p.z - n.z);
      uv.push(0, t * 18, 1, t * 18);
      if (i < segs) {
        const a = i * 2;
        idx.push(a, a + 1, a + 2, a + 1, a + 3, a + 2);
      }
    }
    const geo = new THREE.BufferGeometry();
    geo.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
    geo.setAttribute('uv', new THREE.Float32BufferAttribute(uv, 2));
    geo.setIndex(idx);
    geo.computeVertexNormals();
    const mesh = new THREE.Mesh(geo, mat);
    mesh.receiveShadow = true;
    overworld.add(mesh);
    return mesh;
  }
  const roadMat = toon('#ffffff'); roadMat.map = dirtTex();
  const pathRoad = [[0, 300], [8, 360], [30, 430], [90, 520], [210, 610], [300, 720], [360, 880]];
  ribbon([[0, 300], [-4, 342], [0, 430], [10, 560], [-10, 700]], 14, roadMat);
  ribbon([[300, 0], [360, 10], [470, 40], [580, 80], [700, 90]], 13, roadMat);
  ribbon([[-300, 0], [-380, -40], [-470, -120], [-560, -210], [-640, -300]], 12, roadMat);
  ribbon([[0, -300], [20, -420], [70, -560], [150, -700], [260, -840]], 12, roadMat);
  ribbon([[-470, 430], [-520, 530], [-600, 650], [-680, 760]], 10, roadMat);
  ribbon([[520, 560], [590, 650], [680, 760], [750, 850]], 10, roadMat);

  // ---------- river ----------
  const riverPts = [[-780, -1600], [-620, -1120], [-440, -720], [-300, -380], [-90, -170], [120, -40], [300, 80], [390, 300], [380, 560], [310, 800], [360, 1120], [540, 1600]];
  const waterUniforms = { time: { value: 0 }, deep: { value: new THREE.Color('#2f7f9e') }, shallow: { value: new THREE.Color('#7ed6d3') } };
  const waterMat = new THREE.ShaderMaterial({
    uniforms: waterUniforms,
    transparent: true,
    vertexShader: `
      varying vec2 vUv; varying vec3 vPos;
      uniform float time;
      void main(){ vUv=uv; vec3 p=position; p.y += sin(p.x*0.22+time*1.3)*0.09 + cos(p.z*0.18+time*1.1)*0.07; vPos=p; gl_Position=projectionMatrix*modelViewMatrix*vec4(p,1.0); }
    `,
    fragmentShader: `
      varying vec2 vUv; varying vec3 vPos;
      uniform float time; uniform vec3 deep; uniform vec3 shallow;
      void main(){
        float w = sin(vUv.y*70.0 + time*2.2 + sin(vUv.x*7.0+time)*2.0)*0.5+0.5;
        float ripple = sin(vUv.x*26.0 - time*1.8)*0.5+0.5;
        vec3 col = mix(deep, shallow, w*0.6+ripple*0.25);
        float foam = smoothstep(0.37,0.5,abs(vUv.x-0.5)) * (0.5+0.5*sin(vUv.y*120.0+time*3.0));
        col = mix(col, vec3(0.92,0.98,0.98), foam*0.5);
        gl_FragColor = vec4(col, 0.88);
      }
    `
  });
  ribbon(riverPts, 46, waterMat, 0.12, 200);
  // river rocks
  for (let i = 0; i < 40; i++) {
    const t = i / 40;
    const p = new THREE.CatmullRomCurve3(riverPts.map(v => new THREE.Vector3(v[0], 0.1, v[1]))).getPoint(t);
    const off = (Math.random() - 0.5) * 55;
    const rock = new THREE.Mesh(new THREE.DodecahedronGeometry(0.8 + Math.random() * 2.2, 0), toon('#8c968d'));
    rock.position.set(p.x + off, 0.4, p.z + (Math.random() - 0.5) * 16);
    rock.scale.y = 0.6;
    rock.castShadow = true;
    overworld.add(rock);
  }
  // bridge on east road
  (() => {
    const g = new THREE.Group();
    g.position.set(372, 0, 70);
    g.rotation.y = 0.32;
    const deck = addMesh(g, new THREE.BoxGeometry(22, 1.2, 24), toon('#9c8d74'), 0, 3.4, 0);
    for (let i = 0; i < 5; i++) {
      addMesh(g, new THREE.BoxGeometry(1, 5, 1), toon('#8b7c64'), -9 + i * 4.5, 1.6, 10);
      addMesh(g, new THREE.BoxGeometry(1, 5, 1), toon('#8b7c64'), -9 + i * 4.5, 1.6, -10);
    }
    addMesh(g, new THREE.BoxGeometry(22, 1.2, 1.2), toon('#8b7c64'), 0, 4.6, 11);
    addMesh(g, new THREE.BoxGeometry(22, 1.2, 1.2), toon('#8b7c64'), 0, 4.6, -11);
    overworld.add(g);
  })();

  // ---------- capital ----------
  const city = new THREE.Group();
  overworld.add(city);
  const cobble = toon('#ffffff'); cobble.map = cobbleTex();

  // plaza + streets
  const plaza = new THREE.Mesh(new THREE.CircleGeometry(74, 48), cobble);
  plaza.rotation.x = -Math.PI / 2; plaza.position.set(0, 0.05, -10); plaza.receiveShadow = true;
  city.add(plaza);
  const roadNS = new THREE.Mesh(new THREE.PlaneGeometry(30, 590), cobble);
  roadNS.rotation.x = -Math.PI / 2; roadNS.position.set(0, 0.04, 0); roadNS.receiveShadow = true; city.add(roadNS);
  const roadEW = new THREE.Mesh(new THREE.PlaneGeometry(580, 26), cobble);
  roadEW.rotation.x = -Math.PI / 2; roadEW.position.set(0, 0.045, -60); roadEW.receiveShadow = true; city.add(roadEW);

  // fountain
  (() => {
    const g = new THREE.Group(); g.position.set(0, 0, -10);
    addMesh(g, new THREE.CylinderGeometry(9, 9.6, 1.6, 32), toon('#b9b2a2'), 0, 0.8, 0);
    const water = addMesh(g, new THREE.CylinderGeometry(8.2, 8.2, 0.25, 32), toon('#6fd0dc', { emissive: '#2b7c8c', emissiveIntensity: 0.5, transparent: true, opacity: 0.85 }), 0, 1.6, 0, false);
    addMesh(g, new THREE.CylinderGeometry(1.4, 2.4, 4.2, 12), toon('#c8c1af'), 0, 3.4, 0);
    addMesh(g, new THREE.CylinderGeometry(4.2, 4.8, 0.8, 24), toon('#c8c1af'), 0, 5.4, 0);
    addMesh(g, new THREE.SphereGeometry(1.6, 12, 8), toon('#f4e9c2', { emissive: '#a48a50', emissiveIntensity: 0.4 }), 0, 6.8, 0);
    const beam = addMesh(g, new THREE.CylinderGeometry(0.25, 0.45, 3.2, 8, 1, true), basic('#bdf0f5', { transparent: true, opacity: 0.5 }), 0, 8.4, 0, false);
    city.add(g);
    addColliderCircle(0, -10, 10);
  })();
  // statues & lamps
  for (const [x, z] of [[-34, -55], [34, -55], [-34, 35], [34, 35], [0, 45], [0, -80]]) {
    const g = new THREE.Group(); g.position.set(x, 0, z);
    addMesh(g, new THREE.CylinderGeometry(0.4, 0.6, 6, 8), toon('#5f6670'), 0, 3, 0);
    addMesh(g, new THREE.BoxGeometry(2.2, 0.3, 0.3), toon('#5f6670'), 0, 6, 0);
    const lamp = addMesh(g, new THREE.SphereGeometry(0.45, 8, 6), toon('#ffe5a0', { emissive: '#ffcb63', emissiveIntensity: 1.8 }), 0, 6.1, 0, false);
    city.add(g);
  }

  function gableRoof(parent, w, d, h, mat, y) {
    const shape = new THREE.Shape();
    shape.moveTo(-d / 2, 0); shape.lineTo(d / 2, 0); shape.lineTo(0, h); shape.closePath();
    const geo = new THREE.ExtrudeGeometry(shape, { depth: w, bevelEnabled: false });
    geo.rotateY(Math.PI / 2);
    geo.translate(-w / 2, 0, 0);
    const roof = new THREE.Mesh(geo, mat);
    roof.position.y = y;
    roof.castShadow = true;
    parent.add(roof);
    return roof;
  }

  function building(x, z, w, d, h, opts = {}) {
    const g = new THREE.Group();
    g.position.set(x, 0, z);
    g.rotation.y = opts.rot ?? 0;
    const wall = toon(opts.wall ?? '#e5d7b6');
    addMesh(g, new THREE.BoxGeometry(w, h, d), wall, 0, h / 2, 0);
    // stone base
    addMesh(g, new THREE.BoxGeometry(w + 0.5, 1, d + 0.5), toon('#9b9180'), 0, 0.5, 0);
    gableRoof(g, w + 2.4, d + 2, h * 0.42, toon(opts.roof ?? '#7c4a3d'), h);
    // beams
    const beam = toon(opts.beam ?? '#7a5a3b');
    for (const sx of [-1, 1]) addMesh(g, new THREE.BoxGeometry(0.3, h, 0.3), beam, sx * w / 2, h / 2, d / 2 + 0.12);
    addMesh(g, new THREE.BoxGeometry(w, 0.28, 0.28), beam, 0, h * 0.62, d / 2 + 0.14);
    // door
    addMesh(g, new THREE.BoxGeometry(2.2, 3.4, 0.3), toon('#5d3b24'), 0, 1.9, d / 2 + 0.16);
    // windows
    for (const wx of [-w * 0.28, w * 0.28]) {
      addMesh(g, new THREE.BoxGeometry(1.7, 1.9, 0.2), toon('#ffd98d', { emissive: '#e0a34c', emissiveIntensity: 0.9 }), wx, h * 0.55, d / 2 + 0.18, false);
    }
    if (opts.shop) {
      addMesh(g, new THREE.BoxGeometry(w * 0.9, 0.25, 3), toon('#8a5a3a'), 0, h * 0.86, d / 2 + 2);
    }
    if (opts.sign) {
      const board = addMesh(g, new THREE.BoxGeometry(4.4, 1.5, 0.2), toon('#5d3b24'), -w / 2 - 0.6, h * 0.55, d / 2 + 0.5);
      const label = labelSprite(opts.sign, '', '#f0dfb0');
      label.scale.set(9, 2.25, 1);
      label.position.set(0, h + 4.4, 0);
      g.add(label);
      labels.push(label);
    }
    city.add(g);
    addColliderBox(x, z, w + 1, d + 1);
    return g;
  }

  // palace
  (() => {
    const g = new THREE.Group(); g.position.set(0, 0, -212); city.add(g);
    const wall = toon('#efe4c4'), trim = toon('#cbb578'), roof = toon('#4f6f9d');
    addMesh(g, new THREE.BoxGeometry(118, 20, 78), wall, 0, 10, 0);
    addMesh(g, new THREE.BoxGeometry(122, 1.4, 82), trim, 0, 20.6, 0);
    addMesh(g, new THREE.BoxGeometry(58, 34, 54), wall, 0, 17, -8);
    addMesh(g, new THREE.BoxGeometry(62, 1.6, 58), trim, 0, 34.4, -8);
    gableRoof(g, 64, 60, 17, roof, 34.4);
    addMesh(g, new THREE.BoxGeometry(16, 10, 12), toon('#6b4a34'), 0, 5, 39.2); // grand doors
    addMesh(g, new THREE.BoxGeometry(22, 1, 6), trim, 0, 0.6, 42.2);
    for (const [x, z, s] of [[-31, -8, 1], [31, -8, 1], [-49, 8, 1], [49, 8, 1], [-49, -31, 1], [49, -31, 1]]) {
      addMesh(g, new THREE.CylinderGeometry(5, 6, 30, 10), wall, x, 15, z);
      addMesh(g, new THREE.CylinderGeometry(5.6, 5.6, 1.2, 10), trim, x, 30.4, z);
      const cone = new THREE.Mesh(new THREE.ConeGeometry(7, 12, 10), roof);
      cone.position.set(x, 37, z); cone.castShadow = true; g.add(cone);
    }
