  function buildForest(zone) {
    const { x0, x1, z0, z1, palette, count, name, clearings } = zone;
    const floor = new THREE.Mesh(new THREE.PlaneGeometry(x1 - x0, z1 - z0), toon('#ffffff'));
    floor.material.map = forestFloorTex();
    floor.material.color.set(palette.floor);
    floor.rotation.x = -Math.PI / 2;
    floor.position.set((x0 + x1) / 2, 0.02, (z0 + z1) / 2);
    floor.receiveShadow = true;
    overworld.add(floor);
    const positions = [];
    const trunk = new THREE.InstancedMesh(treeTrunkGeo, trunkMat, count);
    const leaves = new THREE.InstancedMesh(foliageGeo, leafMat, count);
    const leaves2 = new THREE.InstancedMesh(foliageGeo2, leafMat2, count);
    trunk.castShadow = leaves.castShadow = true;
    const m = new THREE.Matrix4(), q = new THREE.Quaternion(), s = new THREE.Vector3(), p = new THREE.Vector3();
    const col = new THREE.Color();
    let placed = 0, attempts = 0;
    while (placed < count && attempts < count * 8) {
      attempts++;
      const x = x0 + 24 + Math.random() * (x1 - x0 - 48);
      const z = z0 + 24 + Math.random() * (z1 - z0 - 48);
      let skip = false;
      for (const c of clearings) {
        if ((x - c[0]) ** 2 + (z - c[1]) ** 2 < (c[2] ** 2)) { skip = true; break; }
      }
      if (skip) continue;
      for (const p2 of portals) {
        if ((x - p2.pos.x) ** 2 + (z - p2.pos.z) ** 2 < 30 * 30) { skip = true; break; }
      }
      if (skip) continue;
      const sc = 0.7 + Math.random() * 0.85;
      const rot = Math.random() * Math.PI * 2;
      q.setFromAxisAngle(new THREE.Vector3(0, 1, 0), rot);
      p.set(x, 0, z);
      s.set(sc, sc * (0.85 + Math.random() * 0.4), sc);
      m.compose(p, q, s);
      trunk.setMatrixAt(placed, m);
      leaves.setMatrixAt(placed, m);
      leaves2.setMatrixAt(placed, m);
      col.setHSL(0.28 + Math.random() * 0.06, 0.34 + Math.random() * 0.2, 0.28 + Math.random() * 0.15);
      leaves.setColorAt(placed, col);
      leaves2.setColorAt(placed, col.clone().offsetHSL(0, 0, 0.05));
      positions.push([x, z, sc]);
      placed++;
    }
    trunk.count = leaves.count = leaves2.count = placed;
    trunk.instanceMatrix.needsUpdate = true;
    leaves.instanceMatrix.needsUpdate = true;
    leaves2.instanceMatrix.needsUpdate = true;
    if (leaves.instanceColor) leaves.instanceColor.needsUpdate = true;
    if (leaves2.instanceColor) leaves2.instanceColor.needsUpdate = true;
    overworld.add(trunk, leaves, leaves2);
    // rocks + mushrooms + ferns
    const rockGeo = new THREE.DodecahedronGeometry(1, 0);
    const rocks = new THREE.InstancedMesh(rockGeo, toon('#7f8a7a'), 90);
    let ri = 0;
    while (ri < 90) {
      const x = x0 + Math.random() * (x1 - x0), z = z0 + Math.random() * (z1 - z0);
      let bad = false;
      for (const c of clearings) if ((x - c[0]) ** 2 + (z - c[1]) ** 2 < (c[2] + 6) ** 2) bad = true;
      if (bad) continue;
      const sc = 0.5 + Math.random() * 2.2;
      p.set(x, sc * 0.3, z); q.setFromEuler(new THREE.Euler(Math.random(), Math.random() * 6, Math.random())); s.set(sc, sc * 0.65, sc);
      m.compose(p, q, s); rocks.setMatrixAt(ri, m); ri++;
    }
    overworld.add(rocks);

    // fireflies
    const fCount = 110;
    const fPos = new Float32Array(fCount * 3);
    for (let i = 0; i < fCount; i++) {
      fPos[i * 3] = x0 + Math.random() * (x1 - x0);
      fPos[i * 3 + 1] = 1 + Math.random() * 7;
      fPos[i * 3 + 2] = z0 + Math.random() * (z1 - z0);
    }
    const fGeo = new THREE.BufferGeometry();
    fGeo.setAttribute('position', new THREE.BufferAttribute(fPos, 3));
    const fireflies = new THREE.Points(fGeo, new THREE.PointsMaterial({ color: '#eaffb0', size: 0.5, transparent: true, opacity: 0.9, depthWrite: false, blending: THREE.AdditiveBlending }));
    overworld.add(fireflies);
    animators.push((dt, t) => { fireflies.position.y = Math.sin(t * 0.6) * 0.4; });

    // zone marker
    const label = labelSprite(name.toUpperCase(), `${x1 - x0} × ${z1 - z0} m`, '#e8e3c0');
    label.position.set((x0 + x1) / 2, 55, z0 + 40);
    label.scale.set(64, 16, 1);
    overworld.add(label);

    return positions;
  }

