@import url('https://fonts.googleapis.com/css2?family=Cinzel:wght@500;600;700;800&family=Crimson+Text:ital,wght@0,400;0,600;1,400&display=swap');

:root {
  --gold: #d8c087;
  --gold-bright: #f4e5b6;
  --gold-dim: #8b7d58;
  --ink: #070d10;
  --panel: rgba(10, 19, 23, .74);
  --line: rgba(214, 193, 135, .32);
  --text: #ece3c9;
  --muted: #a49d86;
  --teal: #7fc2c9;
}

* { box-sizing: border-box; }
html, body, #root { width: 100%; height: 100%; margin: 0; overflow: hidden; }
body {
  font-family: 'Crimson Text', Georgia, serif;
  color: var(--text);
  background: #05090b;
  -webkit-font-smoothing: antialiased;
}
button { font-family: inherit; color: inherit; }
kbd { font-family: 'Cinzel', serif; }

.grain {
  position: fixed; inset: 0; z-index: 60; pointer-events: none; opacity: .1;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.92' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.4'/%3E%3C/svg%3E");
  mix-blend-mode: overlay;
}

/* ---------------- class selection ---------------- */
.select-screen {
  position: relative; width: 100%; height: 100%; overflow: hidden;
  background:
    radial-gradient(ellipse at 50% 30%, rgba(88, 130, 140, .26), transparent 44%),
    radial-gradient(ellipse at 50% 105%, rgba(191, 155, 82, .14), transparent 46%),
    linear-gradient(180deg, #0b171e 0%, #0a1319 48%, #060b0e 100%);
}
.select-screen::before {
  content: ""; position: absolute; inset: 0; pointer-events: none;
  background:
    repeating-linear-gradient(90deg, transparent 0 239px, rgba(219, 197, 137, .04) 239px 240px),
    radial-gradient(ellipse at 50% 55%, transparent 30%, rgba(3, 7, 9, .72) 100%);
}
.select-screen::after {
  content: ""; position: absolute; left: 0; right: 0; bottom: 0; height: 34%;
  background: linear-gradient(transparent, rgba(4, 8, 10, .92)); pointer-events: none;
}
.stage-canvas { position: absolute; inset: 0; width: 100%; height: 100%; }
.select-top {
  position: absolute; z-index: 3; top: 3.2vh; left: 0; right: 0; text-align: center; pointer-events: none;
  animation: fadeDown 1.1s ease both;
}
.eyebrow {
  font-family: 'Cinzel', serif; font-size: 10px; letter-spacing: .62em; color: var(--gold);
  text-transform: uppercase;
}
.select-top h1 {
  font-family: 'Cinzel', serif; font-weight: 800; margin: 2px 0 0; font-size: clamp(34px, 4.6vw, 62px);
  letter-spacing: .22em; line-height: 1.05; color: #f4ead0;
  text-shadow: 0 0 40px rgba(240, 210, 140, .25), 0 4px 16px rgba(0, 0, 0, .8);
  background: linear-gradient(180deg, #fff8e4 15%, #e2ca91 55%, #a98f55 100%);
  -webkit-background-clip: text; background-clip: text; -webkit-text-fill-color: transparent;
}
.subtitle {
  margin-top: 8px; font-size: 14px; letter-spacing: .28em; color: #a9ac9c; text-transform: uppercase;
  font-family: 'Cinzel', serif; font-size: 9px;
}
.select-choice {
  position: absolute; z-index: 3; top: 21.5%; left: 0; right: 0; text-align: center;
  font-family: 'Cinzel', serif; font-size: 11px; letter-spacing: .55em; color: #c3b993;
  pointer-events: none;
}
.select-choice::before, .select-choice::after {
  content: ""; display: inline-block; vertical-align: middle; width: 54px; height: 1px; margin: 0 14px;
  background: linear-gradient(90deg, transparent, var(--gold-dim));
}
.select-choice::after { background: linear-gradient(90deg, var(--gold-dim), transparent); }

.class-deck {
  position: absolute; z-index: 4; left: 50%; bottom: 96px; transform: translateX(-50%);
  display: flex; gap: 14px; width: min(1140px, 94vw);
}
.class-card {
  --c: #eab45f;
  position: relative; flex: 1; min-width: 0; height: 170px; text-align: left; cursor: pointer;
  padding: 16px 18px 14px; border: 1px solid rgba(201, 184, 134, .22);
  background: linear-gradient(160deg, rgba(20, 33, 38, .82), rgba(6, 12, 15, .9));
  backdrop-filter: blur(6px); transition: transform .3s ease, border-color .3s, box-shadow .3s;
  overflow: hidden; clip-path: polygon(0 0, 100% 0, 100% calc(100% - 12px), calc(100% - 12px) 100%, 0 100%);
}
.class-card::before {
  content: ""; position: absolute; inset: 0;
  background: radial-gradient(ellipse at 50% 0%, color-mix(in srgb, var(--c) 22%, transparent), transparent 70%);
  opacity: .4; transition: opacity .3s;
}
.class-card::after {
  content: ""; position: absolute; top: 0; left: 18px; right: 18px; height: 1px;
  background: linear-gradient(90deg, transparent, var(--c), transparent); opacity: .45;
}
.class-card:hover { transform: translateY(-5px); border-color: rgba(216, 192, 135, .55); }
.class-card.active {
  transform: translateY(-10px); border-color: var(--c);
  box-shadow: 0 18px 46px rgba(0, 0, 0, .6), 0 0 30px color-mix(in srgb, var(--c) 18%, transparent), inset 0 0 40px rgba(0, 0, 0, .3);
}
.class-card.active::before { opacity: .8; }
.cc-head { display: flex; justify-content: space-between; align-items: center; position: relative; z-index: 2; }
.cc-order { font-family: 'Cinzel', serif; font-size: 10px; color: var(--c); letter-spacing: .2em; }
.cc-diff { font-size: 9px; text-transform: uppercase; letter-spacing: .16em; color: #8f968a; }
.class-card h2 {
  position: relative; z-index: 2; margin: 8px 0 0; font-family: 'Cinzel', serif; font-size: 22px;
  letter-spacing: .15em; color: #f1e7ce; font-weight: 700;
}
.cc-role {
  position: relative; z-index: 2; font-size: 9px; text-transform: uppercase; letter-spacing: .24em;
  color: var(--c); margin-top: 2px;
}
.cc-specs {
  position: relative; z-index: 2; display: flex; gap: 8px; align-items: center; margin-top: 12px;
  font-family: 'Cinzel', serif; font-size: 8.5px; letter-spacing: .08em; color: #b9b39d;
}
.cc-specs i { width: 3px; height: 3px; border-radius: 50%; background: var(--gold-dim); }
.cc-abilities {
  position: relative; z-index: 2; display: flex; flex-wrap: wrap; gap: 5px; margin-top: 10px;
}
.cc-abilities span {
  font-size: 8.5px; letter-spacing: .08em; text-transform: uppercase; padding: 3px 6px;
  border: 1px solid rgba(214, 193, 135, .17); color: #c9c3ad; background: rgba(0, 0, 0, .18);
}
.select-card-shade { display: none; }
.select-bottom {
  position: absolute; z-index: 5; left: 50%; transform: translateX(-50%); bottom: 18px;
  width: min(1200px, 95vw); display: grid; grid-template-columns: 1fr auto 1fr; align-items: center; gap: 20px;
}
.chosen-desc { font-size: 12px; line-height: 1.45; color: #a6a18c; max-width: 360px; }
.chosen-desc p { margin: 3px 0 0; }
.chosen-role { font-family: 'Cinzel', serif; font-size: 10px; letter-spacing: .2em; color: var(--gold); text-transform: uppercase; }
.begin {
  position: relative; cursor: pointer; padding: 14px 30px; border: 1px solid #b9a46b;
  background: linear-gradient(90deg, rgba(39, 42, 35, .9), rgba(111, 96, 58, .92), rgba(39, 42, 35, .9));
  color: #fff3cd; font-family: 'Cinzel', serif; font-size: 11px; letter-spacing: .26em;
  display: inline-flex; align-items: center; gap: 18px; justify-content: center;
  transition: .25s; clip-path: polygon(8px 0, 100% 0, 100% calc(100% - 8px), calc(100% - 8px) 100%, 0 100%, 0 8px);
  box-shadow: 0 10px 30px rgba(0, 0, 0, .45), inset 0 0 24px rgba(255, 232, 170, .1);
}
.begin:hover { background: linear-gradient(90deg, rgba(65, 60, 43, .95), rgba(154, 130, 72, .95), rgba(65, 60, 43, .95)); color: #fff8e0; box-shadow: 0 10px 34px rgba(0, 0, 0, .5), 0 0 26px rgba(220, 190, 120, .22); }
.begin i { font-style: normal; font-size: 22px; line-height: 1; margin-top: -3px; }
.select-hint { text-align: right; font-family: 'Cinzel', serif; font-size: 8.5px; letter-spacing: .1em; color: #7f8175; }

/* ---------------- game screen ---------------- */
.game-screen {
