.hud { position: absolute; inset: 0; z-index: 5; pointer-events: none; }
.hud > * { pointer-events: none; }
.hud button, .hud .minimap { pointer-events: auto; }

.topbar {
  position: absolute; top: 0; left: 0; right: 0; height: 96px;
