.zone-banner { position: absolute; left: 50%; top: 14px; transform: translateX(-50%); text-align: center; }
.zone-rule { width: 280px; height: 1px; background: linear-gradient(90deg, transparent, rgba(215, 190, 126, .45), transparent); }
.zone-name { font-family: 'Cinzel', serif; font-size: 15px; letter-spacing: .26em; margin-top: 5px; color: #f2e8cf; text-shadow: 0 2px 8px #000; }
.zone-sub { font-size: 10px; letter-spacing: .16em; text-transform: uppercase; color: #ada78f; margin-top: 1px; }
.zone-rank {
