  background: #263126; border: 1px solid #bca76d;
}
.char-meta { flex: 1; min-width: 0; padding-top: 2px; }
.char-name { font-family: 'Cinzel', serif; font-size: 13px; letter-spacing: .16em; color: #f0e6cd; text-shadow: 0 2px 6px #000; }
.char-name span { display: block; font-family: 'Crimson Text', serif; font-size: 10px; letter-spacing: .1em; color: var(--accent); text-transform: uppercase; margin-top: 1px; }
.bar {
  position: relative; height: 12px; margin-top: 7px; background: rgba(22, 20, 16, .88);
