.bar.mp span { font-size: 6px; }
.bar.st { height: 5px; margin-top: 4px; border-color: rgba(150, 170, 130, .2); }
.bar.st i { background: linear-gradient(90deg, #50652e, #9ab95a); }
.xp-line { display: flex; align-items: center; gap: 6px; }
.bar.xp { flex: 1; height: 4px; margin-top: 5px; border: none; background: rgba(0, 0, 0, .5); }
.bar.xp i { background: linear-gradient(90deg, #8b6d2e, #e8cc86); }
.xp-line > span { font-family: 'Cinzel', serif; font-size: 6.5px; letter-spacing: .06em; color: #9d947b; white-space: nowrap; margin-top: 4px; }
.char-buffs { position: absolute; left: 12px; top: 98px; display: flex; gap: 5px; }
.buff {
  font-family: 'Cinzel', serif; font-size: 7px; letter-spacing: .1em; padding: 3px 6px;
  border: 1px solid currentColor; background: rgba(0, 0, 0, .5); animation: buffPulse 1.8s infinite;
}
.buff.gold { color: #ffd479; }
.buff.green { color: #9bf0b2; }
.buff.violet { color: #c9a3ff; }

.right-rail { position: absolute; right: 24px; top: 104px; width: 246px; display: flex; flex-direction: column; gap: 10px; align-items: flex-end; }
.minimap {
  position: relative; width: 236px; height: 178px; padding: 0; cursor: pointer; overflow: hidden;
  border: 1px solid rgba(210, 191, 137, .5); background: #101a1a;
  box-shadow: 0 8px 30px rgba(0, 0, 0, .45), inset 0 0 0 3px rgba(6, 11, 13, .8);
  clip-path: polygon(0 0, 100% 0, 100% calc(100% - 10px), calc(100% - 10px) 100%, 0 100%);
}
.minimap svg { width: 100%; height: 100%; display: block; }
.minimap::after { content: ""; position: absolute; inset: 0; pointer-events: none; background: radial-gradient(ellipse at 50% 50%, transparent 55%, rgba(3, 8, 10, .55)); }
.mm-label {
  position: absolute; left: 7px; bottom: 6px; font-family: 'Cinzel', serif; font-size: 6.5px;
  letter-spacing: .24em; color: #c7b98e; text-shadow: 0 1px 4px #000;
}
.quest-card {
  width: 246px; padding: 10px 12px 11px; background: linear-gradient(180deg, rgba(6, 13, 16, .8), rgba(6, 13, 16, .48));
  border: 1px solid rgba(201, 183, 132, .22); border-right: none;
  box-shadow: -8px 10px 30px rgba(0, 0, 0, .25);
}
.quest-head { display: flex; justify-content: space-between; align-items: center; margin-bottom: 7px; }
.quest-head small { font-family: 'Cinzel', serif; font-size: 7.5px; letter-spacing: .2em; color: var(--gold); }
.quest-head span { font-family: 'Cinzel', serif; font-size: 8px; color: #141d1c; background: var(--gold); padding: 1px 6px; }
.quest { padding: 7px 0 6px; border-top: 1px solid rgba(214, 193, 135, .12); }
.quest-title { font-family: 'Cinzel', serif; font-size: 9.5px; letter-spacing: .08em; color: #efe5ca; }
.quest-desc { font-size: 10px; color: #a8a290; line-height: 1.3; margin-top: 2px; }
.quest-progress { display: flex; gap: 6px; align-items: center; margin-top: 5px; }
.quest-progress div { flex: 1; height: 4px; background: rgba(0, 0, 0, .5); overflow: hidden; }
.quest-progress i { display: block; height: 100%; background: linear-gradient(90deg, #8c743a, #e5ca85); }
.quest-progress b { font-family: 'Cinzel', serif; font-size: 7px; color: #c8b984; }
.quest-reward { font-size: 8.5px; color: #8d876f; margin-top: 3px; letter-spacing: .04em; }
.quest-done { font-size: 10px; color: #a8a290; line-height: 1.35; padding: 4px 0; }
.more-quests { font-family: 'Cinzel', serif; font-size: 7px; letter-spacing: .1em; color: #8d876f; margin-top: 4px; }
.wallet {
  display: flex; align-items: center; gap: 5px; padding: 5px 9px; align-self: flex-end;
  background: rgba(5, 11, 13, .7); border: 1px solid rgba(201, 183, 132, .18);
