}
.wallet .coin { color: #e3c777; font-size: 9px; }
.wallet b { font-family: 'Cinzel', serif; font-size: 10px; }
.wallet em { font-style: normal; font-size: 8px; letter-spacing: .1em; color: #8c8571; text-transform: uppercase; margin-right: 4px; }
.wallet-sep { width: 1px; height: 12px; background: rgba(201, 183, 132, .25); margin: 0 4px; }

.boss-bar {
  position: absolute; left: 50%; top: 96px; transform: translateX(-50%); width: min(520px, 46vw);
  padding: 7px 12px 8px; background: rgba(5, 10, 12, .72); border: 1px solid rgba(206, 182, 126, .4);
  box-shadow: 0 10px 30px rgba(0, 0, 0, .4);
}
.boss-head { display: flex; justify-content: space-between; font-family: 'Cinzel', serif; font-size: 10px; letter-spacing: .12em; color: #f1dfb4; }
.boss-head b { font-size: 7px; color: #c2745c; }
.boss-track { height: 8px; background: #22110f; margin-top: 5px; border: 1px solid #4a2c25; transform: skewX(-12deg); overflow: hidden; }
.boss-track i { display: block; height: 100%; background: linear-gradient(90deg, #7c1e22, #c44833 60%, #e08458); transition: width .2s; }
.boss-hp { text-align: right; font-family: 'Cinzel', serif; font-size: 7px; color: #9f9179; margin-top: 2px; }
.target-card {
  position: absolute; left: 50%; top: 100px; transform: translateX(-50%); width: 310px;
  display: flex; align-items: center; gap: 8px; padding: 5px 9px;
  background: rgba(4, 9, 11, .55); border: 1px solid rgba(201, 183, 132, .16);
}
.t-name { font-family: 'Cinzel', serif; font-size: 8px; letter-spacing: .06em; color: #e4d8b8; white-space: nowrap; }
.t-track { flex: 1; height: 4px; background: #2c1411; overflow: hidden; }
.t-track i { display: block; height: 100%; background: linear-gradient(90deg, #a03a2a, #e0925e); }
.t-rank { font-family: 'Cinzel', serif; font-size: 7px; color: #c0a568; }

.action-wrap { position: absolute; left: 50%; bottom: 20px; transform: translateX(-50%); display: flex; flex-direction: column; align-items: center; }
.prompt-slot { height: 34px; display: flex; align-items: flex-end; justify-content: center; }
.interact-prompt {
  display: flex; align-items: center; gap: 8px; padding: 5px 12px 5px 6px;
  background: rgba(5, 12, 14, .86); border: 1px solid rgba(218, 195, 135, .4);
  box-shadow: 0 6px 22px rgba(0, 0, 0, .45); animation: promptIn .25s ease;
}
.interact-prompt kbd {
  width: 20px; height: 20px; display: grid; place-items: center; border: 1px solid var(--gold);
  color: var(--gold-bright); background: rgba(80, 67, 37, .4); font-size: 9px;
}
.interact-prompt span { font-family: 'Cinzel', serif; font-size: 9px; letter-spacing: .1em; color: #f0e4c2; }
.interact-prompt em { font-style: normal; font-size: 9px; color: #99917a; }
.actionbar { display: flex; align-items: flex-end; gap: 7px; padding: 7px 12px; background: linear-gradient(180deg, transparent, rgba(4, 9, 11, .58)); }
.slot {
  position: relative; width: 66px; height: 66px; border: 1px solid rgba(197, 179, 128, .42);
  background: radial-gradient(circle at 50% 35%, rgba(43, 59, 62, .9), rgba(7, 13, 15, .95));
  color: #e5d8b6; cursor: pointer; display: grid; place-items: center;
  clip-path: polygon(9px 0, 100% 0, 100% calc(100% - 9px), calc(100% - 9px) 100%, 0 100%, 0 9px);
  transition: .16s;
}
.slot:hover { border-color: var(--accent); color: #fff4d2; box-shadow: 0 0 18px color-mix(in srgb, var(--accent) 25%, transparent); }
.slot.ability .slot-glyph { color: var(--accent); filter: drop-shadow(0 0 7px color-mix(in srgb, var(--accent) 50%, transparent)); }
.slot .key {
  position: absolute; top: -6px; right: -3px; min-width: 19px; height: 17px; padding: 0 3px;
  display: grid; place-items: center; background: #1b2422; border: 1px solid rgba(205, 185, 132, .55);
  font-family: 'Cinzel', serif; font-size: 7px; color: #d9cba1;
}
.slot em {
  position: absolute; bottom: -14px; left: -8px; right: -8px; font-style: normal;
  font-family: 'Cinzel', serif; font-size: 6.5px; letter-spacing: .06em; color: #b2a88d;
  text-align: center; white-space: nowrap; text-shadow: 0 1px 3px #000;
}
.slot .cost {
  position: absolute; bottom: 2px; right: 4px; font-size: 8px; color: #7fb5d6;
}
.slot.basic { width: 62px; height: 62px; }
.slot.small { width: 50px; height: 54px; }
.slot.small em { bottom: -14px; }
.slot .count {
  position: absolute; bottom: 1px; right: 4px; font-family: 'Cinzel', serif; font-size: 9px; color: #e9dab4;
}
.slot.potion .key { background: #2a1c19; }
.slot.locked { opacity: .55; }
.slot.locked .slot-glyph { filter: none; color: #7d8790; }
.cooldown {
  position: absolute; inset: 0; display: grid; place-items: center; pointer-events: none;
  color: #fff3d2; font-family: 'Cinzel', serif; font-size: 11px;
  text-shadow: 0 1px 4px #000;
}
.cooldown b { font-weight: 600; }
.divider { width: 1px; height: 44px; background: rgba(201, 183, 132, .22); margin: 0 3px; align-self: center; }
.control-hint {
  position: absolute; right: 24px; bottom: 22px; display: flex; gap: 12px;
  font-size: 8px; color: #807d6d; letter-spacing: .04em;
}
.control-hint kbd {
  padding: 2px 4px; border: 1px solid rgba(190, 174, 128, .24); color: #b8ad90;
  font-size: 7px; margin-right: 3px;
}

.damage-layer { position: absolute; inset: 0; pointer-events: none; overflow: hidden; }
.dmg {
  position: absolute; font-family: 'Cinzel', serif; font-size: 18px; font-weight: 700;
  text-shadow: 0 2px 6px #000, 0 0 14px currentColor; animation: dmgFloat .95s ease-out forwards;
  transform: translate(-50%, -50%);
