const { chromium } = require('playwright-core');
(async () => {
  const browser = await chromium.launch({
    executablePath: '/usr/bin/chromium',
    headless: true,
    args: ['--no-sandbox', '--use-gl=angle', '--use-angle=swiftshader', '--enable-unsafe-swiftshader', '--disable-dev-shm-usage', '--disable-gpu-sandbox']
  });
  const page = await browser.newPage({ viewport: { width: 1280, height: 720 }, deviceScaleFactor: 1 });
  const errors = [];
  page.on('console', m => { if (m.type() === 'error') errors.push('CONSOLE: ' + m.text()); });
  page.on('pageerror', e => errors.push('PAGEERROR: ' + e.message + '\n' + e.stack));
  await page.goto('http://localhost:3002', { waitUntil: 'networkidle' });
  await page.waitForTimeout(3500);
  await page.screenshot({ path: 'screenshots/select.jpg', type: 'jpeg', quality: 82 });
  console.log('select shot done');
  await page.click('.begin');
  await page.waitForTimeout(4000);
  await page.screenshot({ path: 'screenshots/intro.jpg', type: 'jpeg', quality: 82 });
  console.log('intro shot done');
  await page.click('.intro-card .begin');
  await page.waitForTimeout(3500);
  await page.screenshot({ path: 'screenshots/game.jpg', type: 'jpeg', quality: 82 });
  console.log('game shot done');
  console.log('ERRORS:', JSON.stringify(errors, null, 2));
  await browser.close();
})();

