input.content:
const { chromium } = require('playwright-core');
(async () => {
  const browser = await chromium.launch({
    executablePath: '/usr/bin/chromium',
    headless: true,
    args: ['--no-sandbox', '--use-gl=angle', '--use-angle=swiftshader', '--enable-unsafe-swiftshader', '--disable-dev-shm-usage']
  });
  const page = await browser.newPage({ viewport: { width: 1280, height: 720 }, deviceScaleFactor: 1 });
  const errors = [];
  page.on('console', m => { if (m.type() === 'error') errors.push('CONSOLE: ' + m.text()); });
  page.on('pageerror', e => errors.push('PAGEERROR: ' + e.message + '\n' + e.stack));
  await page.goto('http://localhost:3002', { waitUntil: 'networkidle' });
  await page.waitForTimeout(2500);
  await page.screenshot({ path: 'screenshots/select.jpg', type: 'jpeg', quality: 82 });

  // pick archer to inspect its model
  await page.click('.class-card:nth-child(2)');
  await page.waitForTimeout(1200);
  await page.screenshot({ path: 'screenshots/select-archer.jpg', type: 'jpeg', quality: 82 });

  await page.click('.begin');
  await page.waitForTimeout(2500);
  await page.screenshot({ path: 'screenshots/intro.jpg', type: 'jpeg', quality: 82 });
  await page.click('.intro-card .begin');
  await page.waitForTimeout(2600);
  await page.screenshot({ path: 'screenshots/game.jpg', type: 'jpeg', quality: 82 });

  // move forward and cast
  await page.keyboard.down('w');
  await page.waitForTimeout(2200);
  await page.keyboard.up('w');
  await page.keyboard.press('q');
  await page.waitForTimeout(200);
  await page.screenshot({ path: 'screenshots/game-cast.jpg', type: 'jpeg', quality: 82 });
  await page.waitForTimeout(2000);

  // teleport near a dungeon portal
  await page.evaluate(() => {
    const g = window.__elyndor;
    g.player.pos.set(-700, 0, -790);
    g.camYaw = Math.PI;
    g.pushHud();
  });
  await page.waitForTimeout(2200);
  await page.screenshot({ path: 'screenshots/forest.jpg', type: 'jpeg', quality: 82 });

  // open map
  await page.keyboard.press('m');
  await page.waitForTimeout(1000);
  await page.screenshot({ path: 'screenshots/map.jpg', type: 'jpeg', quality: 82 });
  await page.keyboard.press('Escape');
  await page.waitForTimeout(500);

  // enter dungeon directly
  await page.evaluate(() => { window.__elyndor.enterDungeon('hollow'); });
  await page.waitForTimeout(2500);
  await page.screenshot({ path: 'screenshots/dungeon.jpg', type: 'jpeg', quality: 82 });

  // simulate combat check
  const info = await page.evaluate(() => {
    const g = window.__elyndor;
    const before = g.enemies.filter(e => e.interior === 'hollow' && !e.dead).length;
    const b = g.boss;
    if (b) { g.dealDamage(b, 2000, { crit: true }); }
    return { enemies: before, bossHp: b?.hp, cleared: [...g.cleared], quests: g.quests.map(q => [q.id, q.progress, q.done]) };
  });
  await page.waitForTimeout(1800);
  await page.screenshot({ path: 'screenshots/dungeon-clear.jpg', type: 'jpeg', quality: 82 });
  console.log('INFO', JSON.stringify(info));
  console.log('ERRORS:', JSON.stringify(errors, null, 2));
  await browser.close();
})();

