const { chromium } = require('playwright-core');
(async () => {
  const browser = await chromium.launch({
    executablePath: '/usr/bin/chromium',
    headless: true,
    args: ['--no-sandbox', '--use-gl=angle', '--use-angle=swiftshader', '--enable-unsafe-swiftshader', '--disable-dev-shm-usage']
  });
  const page = await browser.newPage({ viewport: { width: 1280, height: 720 }, deviceScaleFactor: 1 });
  const errors = [];
  page.on('pageerror', e => errors.push('PAGEERROR: ' + e.message));
  page.on('console', m => { if (m.type() === 'error') errors.push('CONSOLE: ' + m.text()); });
  await page.goto('http://localhost:3002', { waitUntil: 'networkidle' });
  await page.waitForTimeout(1500);
  await page.click('.begin');
  await page.waitForTimeout(800);
  await page.click('.intro-card .begin');
  await page.waitForTimeout(1500);
  const fps = await page.evaluate(async () => {
    let n = 0; const t0 = performance.now();
    await new Promise(r => { const step = () => { n++; if (performance.now() - t0 < 2000) requestAnimationFrame(step); else r(); }; requestAnimationFrame(step); });
    return Math.round(n / ((performance.now() - t0) / 1000));
  });
  console.log('FPS approx', fps);
  const before = await page.evaluate(() => {
    const g = window.__elyndor;
    return {
      cam: g.camera.position.toArray().map(v => +v.toFixed(2)),
      bg: g.scene.background?.getHexString?.(),
      fog: g.scene.fog.color.getHexString(), near: g.scene.fog.near, far: g.scene.fog.far,
      sun: g.sun.intensity, hemi: g.hemi.intensity,
      xp: g.xp, xpNext: g.xpNext, lvl: g.level
    };
  });
  console.log('BEFORE', JSON.stringify(before));
  await page.evaluate(() => { window.__elyndor.enterDungeon('hollow'); });
  await page.waitForTimeout(2500);
  const after = await page.evaluate(() => {
    const g = window.__elyndor;
    return {
      cam: g.camera.position.toArray().map(v => +v.toFixed(2)),
      player: g.player.pos.toArray(),
      desiredCamPos: g.camPos.toArray().map(v => +v.toFixed(2)),
      bg: g.scene.background?.getHexString?.(),
      fog: g.scene.fog.color.getHexString(), near: g.scene.fog.near, far: g.scene.fog.far,
      sun: g.sun.intensity, hemi: g.hemi.intensity, inside: g.insideDungeon,
      canvas: [g.renderer.domElement.width, g.renderer.domElement.height],
      boss: g.boss && { hp: g.boss.hp, maxHp: g.boss.maxHp, speed: g.boss.speed, xp: g.boss.xp, gold: g.boss.gold, radius: g.boss.radius }
    };
  });
  console.log('AFTER', JSON.stringify(after, null, 1));
  await page.screenshot({ path: 'screenshots/dungeon-debug.jpg', type: 'jpeg', quality: 82 });
  console.log('ERRORS', JSON.stringify(errors, null, 2));
  await browser.close();
})();

