(() => {
  const mk = (x, z, r, h, snow = true) => {
    const g = new THREE.Group(); g.position.set(x, 0, z); overworld.add(g);
    const base = new THREE.Mesh(new THREE.ConeGeometry(r, h, 7), toon('#77879a'));
    base.position.y = h / 2 - 2; base.castShadow = true; g.add(base);
    const mid = new THREE.Mesh(new THREE.ConeGeometry(r * 0.62, h * 0.55, 7), toon('#8b9aab'));
    mid.position.y = h * 0.62 - 2; g.add(mid);
    if (snow) {
      const cap = new THREE.Mesh(new THREE.ConeGeometry(r * 0.33, h * 0.28, 7), toon('#eef3f7'));
      cap.position.y = h * 0.9 - 2; g.add(cap);
    }
    // foothills
    for (let i = 0; i < 3; i++) {
      const a = Math.random() * Math.PI * 2;
      const f = new THREE.Mesh(new THREE.ConeGeometry(r * (0.45 + Math.random() * 0.3), h * (0.25 + Math.random() * 0.2), 6), toon('#6f8663'));
