input.content:
const { chromium } = require('playwright-core');
(async () => {
  const browser = await chromium.launch({
    executablePath: '/usr/bin/chromium',
    headless: true,
    args: ['--no-sandbox', '--use-gl=angle', '--use-angle=swiftshader', '--enable-unsafe-swiftshader', '--disable-dev-shm-usage']
  });
  const page = await browser.newPage({ viewport: { width: 1280, height: 720 }, deviceScaleFactor: 1 });
  const errors = [];
  page.on('console', m => { if (m.type() === 'error') errors.push('CONSOLE: ' + m.text()); });
  page.on('pageerror', e => errors.push('PAGEERROR: ' + e.message + '\n' + e.stack));
  await page.goto('http://localhost:3002', { waitUntil: 'networkidle' });
  await page.waitForTimeout(1800);
  await page.screenshot({ path: 'screenshots/select.jpg', type: 'jpeg', quality: 84 });

  await page.click('.begin');
  await page.waitForTimeout(1800);
  await page.click('.intro-card .begin');
  await page.waitForTimeout(1200);
  const meta = await page.evaluate(() => {
    const g = window.__elyndor;
    return { low: g.lowQuality, gpu: g.gpuName, shadows: g.renderer.shadowMap.enabled, pixelRatio: g.renderer.getPixelRatio() };
  });
  console.log('QUALITY', JSON.stringify(meta));
  await page.evaluate(() => window.__elyndor.simulate(2.5));
  await page.waitForTimeout(900);
  await page.screenshot({ path: 'screenshots/game.jpg', type: 'jpeg', quality: 84 });

  // cast all three abilities for the swordsman
  await page.evaluate(() => {
    const g = window.__elyndor;
    g.player.mp = g.player.maxMp;
    g.useAbility('q');
    g.simulate(0.2);
  });
  await page.screenshot({ path: 'screenshots/cast.jpg', type: 'jpeg', quality: 84 });
  await page.evaluate(() => { const g = window.__elyndor; g.player.mp = g.player.maxMp; g.useAbility('e'); g.simulate(0.15); });
  await page.screenshot({ path: 'screenshots/cast2.jpg', type: 'jpeg', quality: 84 });
  await page.evaluate(() => { const g = window.__elyndor; g.useAbility('r'); g.simulate(0.4); });
  await page.screenshot({ path: 'screenshots/cast3.jpg', type: 'jpeg', quality: 84 });

  // forest near the beginner dungeon
  await page.evaluate(() => {
    const g = window.__elyndor;
    g.player.pos.set(-700, 0, -770);
    g.camYaw = Math.PI;
    g.camPitch = 0.2;
    g.simulate(2.2);
  });
  await page.waitForTimeout(700);
  await page.screenshot({ path: 'screenshots/forest.jpg', type: 'jpeg', quality: 84 });

  // map
  await page.keyboard.press('m');
  await page.waitForTimeout(900);
  await page.screenshot({ path: 'screenshots/map.jpg', type: 'jpeg', quality: 84 });
  await page.keyboard.press('Escape');
  await page.waitForTimeout(400);

  // dungeon
  await page.evaluate(() => { const g = window.__elyndor; g.enterDungeon('hollow'); g.simulate(3); });
  await page.waitForTimeout(900);
  await page.screenshot({ path: 'screenshots/dungeon.jpg', type: 'jpeg', quality: 84 });

  const info = await page.evaluate(() => {
    const g = window.__elyndor;
    const b = g.boss;
    const before = g.enemies.filter(e => e.interior === 'hollow' && !e.dead).length;
    const stats = { before, boss: b && { hp: b.hp, maxHp: b.maxHp, speed: b.speed, xp: b.xp, radius: b.radius, name: b.name } };
    if (b) g.dealDamage(b, 4000, { crit: true });
    g.simulate(1.2);
    return { ...stats, cleared: [...g.cleared], quests: g.quests.map(q => [q.id, q.progress, q.done]), xp: g.xp, level: g.level, gold: g.gold };
  });
  await page.waitForTimeout(700);
  await page.screenshot({ path: 'screenshots/dungeon-clear.jpg', type: 'jpeg', quality: 84 });
  console.log('INFO', JSON.stringify(info));
  console.log('ERRORS:', JSON.stringify(errors, null, 2));
  await browser.close();
})();

