const { chromium } = require('playwright-core');
(async () => {
  const browser = await chromium.launch({ executablePath: '/usr/bin/chromium', headless: true, args: ['--no-sandbox', '--use-gl=angle', '--use-angle=swiftshader', '--enable-unsafe-swiftshader', '--disable-dev-shm-usage'] });
  const page = await browser.newPage({ viewport: { width: 1280, height: 720 } });
  page.on('pageerror', e => console.log('PAGEERROR', e.message));
  await page.goto('http://localhost:3002', { waitUntil: 'networkidle' });
  await page.waitForTimeout(1200);
  await page.click('.begin');
  await page.waitForSelector('.intro-card .begin', { timeout: 60000 });
  await page.click('.intro-card .begin');
  await page.waitForTimeout(1200);
  await page.evaluate(() => { const g = window.__elyndor; g.enterDungeon('hollow'); g.simulate(3); });
  const st = await page.evaluate(() => {
    const g = window.__elyndor;
    return {
      bg: g.scene.background.getHexString(), fog: g.scene.fog.color.getHexString(), near: g.scene.fog.near, far: g.scene.fog.far,
      sun: g.sun.intensity, hemi: g.hemi.intensity, inside: g.insideDungeon, sky: g.sky.visible,
      interiorVisible: Object.fromEntries(Object.entries(g.world.dungeonInteriors).map(([k, v]) => [k, v.group.visible])),
      lights: g.world.dungeonInteriors.hollow.group.children.filter(c => c.isLight).map(c => [c.type, c.intensity, c.distance]),
      player: g.player.pos.toArray(), boss: g.boss && g.boss.mesh.position.toArray()
    };
  });
  console.log(JSON.stringify(st, null, 1));
  await page.screenshot({ path: 'screenshots/dungeon-debug.jpg', type: 'jpeg', quality: 84 });
  await browser.close();
})();

