    const g = window.__elyndor;
    g.enterDungeon('hollow');
    g.simulate(2);
    const res = [];
    g.world.dungeonInteriors.hollow.group.traverse(o => {
      if (!o.isMesh && !o.isSprite && !o.isPoints) return;
      const m = o.material;
      const mats = m ? (Array.isArray(m) ? m : [m]) : [];
      for (const mm of mats) {
        if (!mm) continue;
        const p = new (o.position.constructor)();
        o.getWorldPosition(p);
        res.push({
          type: o.type, geo: o.geometry?.type,
          mat: mm.type, color: mm.color ? '#' + mm.color.getHexString() : null,
          opacity: mm.opacity, blending: mm.blending, transparent: mm.transparent,
          pos: p.toArray().map(v => +v.toFixed(1)),
          scale: o.scale.toArray().map(v => +v.toFixed(1)),
          map: !!mm.map, visible: o.visible
        });
      }
    });
    return { res, fog: g.scene.fog && { c: g.scene.fog.color.getHexString(), n: g.scene.fog.near, f: g.scene.fog.far }, emb: g.scene.environment?.type };
  });
  console.log(JSON.stringify(out, null, 1));
  await browser.close();
})();

