  const browser = await chromium.launch({ executablePath: '/usr/bin/chromium', headless: true, args: ['--no-sandbox', '--use-gl=angle', '--use-angle=swiftshader', '--enable-unsafe-swiftshader', '--disable-dev-shm-usage'] });
  const page = await browser.newPage({ viewport: { width: 1280, height: 720 } });
  await page.goto('http://localhost:3002', { waitUntil: 'networkidle' });
  await page.waitForTimeout(1000);
  await page.click('.begin');
  await page.waitForSelector('.intro-card .begin', { timeout: 60000 });
  await page.click('.intro-card .begin');
  await page.waitForTimeout(1000);
  const out = await page.evaluate(() => {
    const g = window.__elyndor;
    g.enterDungeon('hollow');
    g.simulate(2);
    const res = [];
    g.scene.traverse(o => {
      const m = o.material;
      if (!m || Array.isArray(m)) return;
      if (!m.transparent) return;
      if (m.blending !== 2 && !(m.type === 'PointsMaterial')) return;
      const p = new (o.position.constructor)();
      o.getWorldPosition(p);
      if (Math.max(p.x, p.y, p.z, -p.x, -p.y, -p.z) > 300) return;
      res.push({
        type: o.type, parent: o.parent?.type, geo: o.geometry?.type,
        params: o.geometry?.parameters ? Object.fromEntries(Object.entries(o.geometry.parameters).filter(([k]) => ['radius','width','height','innerRadius','outerRadius'].includes(k))) : null,
        color: m.color ? '#' + m.color.getHexString() : null,
        opacity: +(m.opacity ?? 1).toFixed(2), map: !!m.map,
        pos: p.toArray().map(v => +v.toFixed(1)),
        scale: o.scale.toArray().map(v => +v.toFixed(2)),
        visible: o.visible, inScene: o.parent?.type === 'Scene'
      });
    });
    return res;
  });
  console.log(JSON.stringify(out, null, 1));
  await browser.close();
})();

