    const g = window.__elyndor;
    g.enterDungeon('hollow');
    g.simulate(2);
    g.renderer.render(g.scene, g.camera);
    const i = g.renderer.info;
    return { calls: i.render.calls, triangles: i.render.triangles, bg: g.scene.background.getHexString(), fog: g.scene.fog.color.getHexString() };
  });
  console.log('DUNGEON', JSON.stringify(dungeonInfo));
  await page.screenshot({ path: 'screenshots/dungeon-fresh.jpg', type: 'jpeg', quality: 84 });
  await browser.close();
})();

