const { chromium } = require('playwright-core');
(async () => {
  const browser = await chromium.launch({ executablePath: '/usr/bin/chromium', headless: true, args: ['--no-sandbox', '--use-gl=angle', '--use-angle=swiftshader', '--enable-unsafe-swiftshader', '--disable-dev-shm-usage'] });
  const page = await browser.newPage({ viewport: { width: 1280, height: 720 } });
  const errors = [];
  page.on('console', m => { if (m.type() === 'error') errors.push('CONSOLE: ' + m.text()); });
  page.on('pageerror', e => errors.push('PAGEERROR: ' + e.message));
  const log = (...a) => console.log(...a);
  await page.goto('http://localhost:3002', { waitUntil: 'networkidle' });
  await page.waitForTimeout(1000);
  // choose mage to exercise other abilities
  await page.click('.class-card:nth-child(3)');
  await page.click('.begin');
  await page.waitForSelector('.intro-card .begin', { timeout: 60000 });
  await page.click('.intro-card .begin');
  await page.waitForTimeout(1000);

  const r1 = await page.evaluate(() => {
    const g = window.__elyndor;
    const p = g.player;
    const start = p.pos.clone();
    g.keys['w'] = true;
    g.simulate(1.2);
    g.keys['w'] = false;
    const moved = p.pos.distanceTo(start);
    g.keys['d'] = true; g.simulate(0.6); g.keys['d'] = false;
    const strafed = p.pos.distanceTo(start);
    // attack the nearest enemy by teleporting next to it
    const e = g.enemies.find(en => !en.dead && en.insideDungeon === undefined);
    let hit = null;
    if (e) {
      p.pos.copy(e.mesh.position).add(new (p.pos.constructor)(2.5, 0, 0));
      p.facing = Math.atan2(e.mesh.position.x - p.pos.x, e.mesh.position.z - p.pos.z);
      const hpBefore = e.hp;
      g.attack();
      g.simulate(0.4);
      hit = { hpBefore, hpAfter: e.hp, dead: e.dead, quest: g.quests.find(q => q.id === 'q1') };
    }
    // abilities for mage
    const beforeMp = p.mp;
    g.useAbility('q');
    const qCd = g.cooldowns.q;
    g.simulate(0.3);
    g.useAbility('e');
    g.simulate(0.3);
    g.useAbility('r');
    g.simulate(0.5);
    return {
      cls: g.classId, moved: +moved.toFixed(2), strafed: +strafed.toFixed(2), hit,
      mpAfter: +p.mp.toFixed(1), mpBefore: +beforeMp.toFixed(1), qCd: +qCd.toFixed(1),
      projectiles: g.projectiles.length, effects: g.effects.length,
      hud: { hp: p.hp, level: g.level, gold: g.gold }
    };
  });
  log('MOVE/COMBAT', JSON.stringify(r1, null, 1));

  // collision test: run into the palace
  const r2 = await page.evaluate(() => {
    const g = window.__elyndor;
    g.player.pos.set(0, 0, 0);
    g.keys['w'] = true;
    g.simulate(12);
    g.keys['w'] = false;
    return { z: +g.player.pos.z.toFixed(1), blocked: g.player.pos.z < -160 };
  });
  log('COLLISION', JSON.stringify(r2));

  // NPC dialogue + shop
  const r3 = await page.evaluate(() => {
    const g = window.__elyndor;
    const npc = g.world.npcs.find(n => n.data.kind === 'shop');
    g.player.pos.set(npc.data.x, 0, npc.data.z + 2);
    g.interact();
    return { npc: npc?.data.name, kind: npc?.data.kind, blocked: g.blocked };
  });
  await page.waitForTimeout(600);
  const shopVisible = await page.locator('.overlay .shop, .shop-panel, .overlay').count();
  log('SHOP', JSON.stringify({ ...r3, overlay: shopVisible }));
  // close overlay
  const closeBtn = page.locator('.overlay button').first();
  if (await closeBtn.count()) { await closeBtn.click().catch(() => {}); }
  await page.keyboard.press('Escape');
  await page.waitForTimeout(300);

  // dungeon flow
  const r4 = await page.evaluate(() => {
    const g = window.__elyndor;
    g.player.pos.set(0, 0, 0);
    g.enterDungeon('spire');
    g.simulate(2);
    const bossName = g.boss?.name;
    g.dealDamage(g.boss, 99999, { crit: true });
    g.simulate(1.5);
    const cleared = [...g.cleared];
    g.exitDungeon(true);
    return { bossName, cleared, inside: g.insideDungeon, pos: g.player.pos.toArray() };
  });
  log('DUNGEON', JSON.stringify(r4));

  // death + respawn
  const r5 = await page.evaluate(() => {
    const g = window.__elyndor;
    g.player.hp = 1;
    g.damagePlayer(999);
    g.simulate(0.5);
    return { alive: g.alive, hp: g.player.hp };
  });
  await page.waitForTimeout(600);
  const deathOverlay = await page.locator('.overlay').count();
  log('DEATH', JSON.stringify({ ...r5, overlay: deathOverlay }));
  // find any "respawn" style button
  const btns = await page.locator('.overlay button').allInnerTexts();
  log('DEATH BUTTONS', JSON.stringify(btns));
  await page.keyboard.press('Escape');
  await page.waitForTimeout(200);

  // fast travel + map
  await page.evaluate(() => window.__elyndor.travelTo(window.__elyndor.world.pois.find(p => p.kind === 'village')));
  const r6 = await page.evaluate(() => ({ pos: window.__elyndor.player.pos.toArray().map(v => +v.toFixed(1)), zone: window.__elyndor.currentZone?.name }));
  log('TRAVEL', JSON.stringify(r6));
  await page.keyboard.press('m');
  await page.waitForTimeout(500);
  const mapVisible = await page.locator('.world-map, .map-overlay, .overlay').count();
  log('MAP', mapVisible);

  log('ERRORS', JSON.stringify(errors, null, 2));
  await browser.close();
})();

