  const page = await browser.newPage({ viewport: { width: 1280, height: 720 } });
  const msgs = [];
  page.on('console', m => { if (m.type() === 'error' || m.type() === 'warning') msgs.push(m.type().toUpperCase() + ': ' + m.text()); });
  page.on('pageerror', e => msgs.push('PAGEERROR: ' + e.message));
  await page.goto('http://localhost:3002', { waitUntil: 'networkidle' });
  await page.waitForTimeout(1200);
  await page.click('.begin');
  await page.waitForSelector('.intro-card .begin', { timeout: 60000 });
  await page.click('.intro-card .begin');
  await page.waitForTimeout(900);
  const quest = await page.evaluate(() => {
    const g = window.__elyndor;
    g.player.pos.set(-600, 0, -600);
    for (let i = 0; i < 6; i++) {
      const e = g.spawnEnemy('goblin', new (g.player.pos.constructor)(-600 + i * 1.2, 0, -604), { zone: g.world.spawnZones.beginner, depth: 0.1 });
      e.hp = 1;
      g.player.attackTimer = 0;
      g.player.facing = Math.atan2(e.mesh.position.x - g.player.pos.x, e.mesh.position.z - g.player.pos.z);
      g.basicAttack();
      g.simulate(0.5);
    }
    const q = g.quests.find(q => q.id === 'q1');
    return { progress: q.progress, done: q.done, gold: g.gold, level: g.level };
  });
  console.log('QUEST', JSON.stringify(quest));
  console.log('MESSAGES', JSON.stringify(msgs));
  await browser.close();
})();

